"""
call/routing.py — WebSocket URL patterns for the call app.

Imported by appointly/asgi.py and merged with chat routing in the
combined URLRouter.
"""

from django.urls import re_path

from . import consumers

websocket_urlpatterns = [
    # ws://host/ws/call/<call_id>/
    # call_id is a 32-char UUID4 hex (no dashes), generated by the caller.
    re_path(
        r"^ws/call/(?P<call_id>[0-9a-f]{32})/$",
        consumers.CallConsumer.as_asgi(),
        name="ws-call",
    ),

    # ws://host/ws/notify/
    # Personal notification endpoint — one connection per user session.
    re_path(
        r"^ws/notify/$",
        consumers.UserNotifyConsumer.as_asgi(),
        name="ws-notify",
    ),
]
